function ItremGame:initGame()
    local item = nil
    local tempValue = 1
    local child = self.item:getChildren()
    for i, v in ipairs( child or {} ) do
        v:setVisible(false)
    end
    if PURE_JAVA_HALL then require("hall.FriendTable").addEntries(self.listView,self.item) end
    for k, v in ipairs(  self.showSortGameId or {} ) do
        if ((k-1) % 4) == 0 then
            tempValue = 1
            item =self.item:clone()

            local  btn = item:getChildByName("btnGame"..tempValue)
            btn.level = v
            btn:onClick(handler(self, self.onClickEnterRoom))
            ccs.ArmatureDataManager:getInstance():addArmatureFileInfo("hall/res/hallMain/newAnim/anime"..v.."/anime"..v..".png","hall/res/hallMain/newAnim/anime"..v.."/anime"..v..".plist","hall/res/hallMain/newAnim/anime"..v.."/anime"..v..".ExportJson");                         -- 加载动画所用到的数据
            btn:removeAllChildren()
            local armature = ccs.Armature:create("anime"..v)  -- 创建动画对象
            armature:getAnimation():playWithIndex(0)
            armature:setPosition(btn:getContentSize().width/2, btn:getContentSize().height/2)                    -- 设置位置
            --armature:setScale(1.29)
            --armature:getAnimation():play("Tween",100)            -- 设置动画对象执行的动画名称
            btn.level = v
            btn:addChild(armature)                      -- 把动画对象加载到场景内
            btn:setVisible(true)
            self.listView:pushBackCustomItem(item)
        else
            tempValue = tempValue +1
            local  btn = item:getChildByName("btnGame"..tempValue)
            btn.level = v
            btn:onClick(handler(self, self.onClickEnterRoom))
            ccs.ArmatureDataManager:getInstance():addArmatureFileInfo("hall/res/hallMain/newAnim/anime"..v.."/anime"..v..".png","hall/res/hallMain/newAnim/anime"..v.."/anime"..v..".plist","hall/res/hallMain/newAnim/anime"..v.."/anime"..v..".ExportJson");                         -- 加载动画所用到的数据
            btn:removeAllChildren()
            local armature = ccs.Armature:create("anime"..v)  -- 创建动画对象
            armature:getAnimation():playWithIndex(0)
            armature:setPosition(btn:getContentSize().width/2, btn:getContentSize().height/2)                    -- 设置位置
            --armature:setScale(1.29)
            --armature:getAnimation():play("Tween",100)            -- 设置动画对象执行的动画名称

            btn:addChild(armature)                      -- 把动画对象加载到场景内
            btn:setVisible(true)
        end
    end
end
function ItremGame:onClickEnterRoom(event)
    self:enterRoom(event.target.level)
end
function ItremGame:enterRoom(level)
    if g_hallMainLayer then
        local HallMainLayer = g_hallMainLayer
        local data = HallMainLayer:getCurData()
        if data then
            dump(data.roleType,"data.roleType--")
            HallMainLayer.familyMainlayer = FamilyMainLayer.new(data, HallMainLayer, level):addTo(HallMainLayer)
            USER_INFO["family_data"] = data
            FamilyData:SetFamilyId(data.key)
        else
            viewMgr:showTip({text = "您还没有联盟，请先加入联盟"})
        end
    end
end
return ItremGame